// pre-commit hook：本地兜底，CI 之前的最后一道防线
// .husky/pre-commit
npx lint-staged             # 只 lint staged 文件
npx tsc --noEmit            # 类型检查
npm run test:changed        # 只跑被影响文件的测试

// package.json
"lint-staged": {
  "*.{ts,tsx}": ["eslint --fix", "prettier --write"],
  "*.{ts,tsx,json,md}": ["prettier --write"]
}

